mkdir -p site
head -c 1000000 /dev/urandom > site/slow.bin
cp site/slow.bin site/fast.bin
surl --allow-anonymous --directory site --fault "delay;stage=command;command=RETR;path=/slow.bin;ms=3000" ftp://127.0.0.1:8080/ &
